CREATE TABLE IF NOT EXISTS fixed_assets(asset_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,asset_code TEXT NOT NULL,asset_name TEXT NOT NULL,category TEXT,location_id TEXT,acquisition_date TEXT NOT NULL,acquisition_cost NUMERIC NOT NULL,capitalized_cost NUMERIC NOT NULL DEFAULT 0,useful_life_months INTEGER NOT NULL,depreciation_method TEXT NOT NULL DEFAULT 'STRAIGHT_LINE',residual_value NUMERIC NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'ACTIVE',disposed_date TEXT,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,asset_code));
CREATE TABLE IF NOT EXISTS asset_depreciation(asset_depreciation_id TEXT PRIMARY KEY,asset_id TEXT NOT NULL,period_key TEXT NOT NULL,depreciation_amount NUMERIC NOT NULL,accumulated_depreciation NUMERIC NOT NULL,net_book_value NUMERIC NOT NULL,posted INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(asset_id,period_key));
CREATE TABLE IF NOT EXISTS asset_disposals(disposal_id TEXT PRIMARY KEY,asset_id TEXT NOT NULL,disposal_date TEXT NOT NULL,proceeds NUMERIC NOT NULL DEFAULT 0,book_value NUMERIC NOT NULL,gain_loss NUMERIC NOT NULL,reason TEXT,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS loans(loan_id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,entity_id TEXT NOT NULL,loan_code TEXT NOT NULL,lender_name TEXT NOT NULL,principal NUMERIC NOT NULL,interest_rate NUMERIC NOT NULL DEFAULT 0,tenure_months INTEGER NOT NULL,start_date TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'ACTIVE',created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(organization_id,loan_code));
CREATE TABLE IF NOT EXISTS loan_schedule(schedule_id TEXT PRIMARY KEY,loan_id TEXT NOT NULL,installment_no INTEGER NOT NULL,due_date TEXT NOT NULL,principal_due NUMERIC NOT NULL,interest_due NUMERIC NOT NULL,total_due NUMERIC NOT NULL,paid_amount NUMERIC NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'DUE',UNIQUE(loan_id,installment_no));
CREATE TABLE IF NOT EXISTS loan_payments(payment_id TEXT PRIMARY KEY,loan_id TEXT NOT NULL,installment_no INTEGER NOT NULL,payment_date TEXT NOT NULL,amount NUMERIC NOT NULL,reference TEXT,created_by TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
